def _session(session, opened_at):
    from .data import SessionBounds
    if isinstance(session, Mapping):
        session = SessionBounds(str(session["session_id"]), session["session_open"], session["session_close"])
    if not session.contains(opened_at):
        raise ContractError("Recovery candle is outside its exact session quarter")
    # Keep the independent session proof; normalize the quarter clock once.
    opened = _utc(opened_at)
    if opened != opened.floor(_SESSION_QUARTER):
        raise ContractError("Recovery candle is outside its exact session quarter")
    return {"session_id": str(session.session_id), "session_open": _utc(session.opened_at).isoformat(),
            "session_close": _utc(session.closed_at).isoformat()}

instant.source:
def instant(value: str | datetime) -> datetime:
    try:
        result = value if isinstance(value, datetime) else datetime.fromisoformat(value.replace("Z", "+00:00"))
    except (ValueError, TypeError, AttributeError) as exc:
        raise ContractError("Timezone-aware timestamp required") from exc
    if result.tzinfo is None or result.utcoffset() is None:
        raise ContractError("Timezone-aware timestamp required")
    return result.astimezone(timezone.utc)

utc.source:
def utc(value) -> pd.Timestamp:
    """Require timezone awareness; never guess the host timezone."""
    return pd.Timestamp(instant(value))

SessionBounds.source:
@dataclass(frozen=True)
class SessionBounds:
    session_id: str
    opened_at: str
    closed_at: str
    policy: str = "explicit-session-bounds"

    def contains(self, opened_at, duration=STEP) -> bool:
        start = utc(opened_at)
        return utc(self.opened_at) <= start and start + duration <= utc(self.closed_at)
